// Preload for web pages in Hog tabs (generated by stage.mjs from
// preload-page.template.cjs). Same as the Linux shell's page user scripts:
// the edge grips / page menus script and the window.ethereum provider run in
// the page's own world before its scripts, and talk to Hog through
// window.webkit.messageHandlers.hogedge.
"use strict";
const { contextBridge, ipcRenderer, webFrame } = require("electron");

contextBridge.exposeInMainWorld("webkit", {
  messageHandlers: {
    hogedge: { postMessage: (message) => ipcRenderer.send("hogedge", String(message)) },
  },
});

// From hog: EDGE_GRIP_SCRIPT (top frame only).
const EDGE_GRIP = function () {
/*@EDGE_GRIP_SCRIPT@*/
};
// public/dapp-provider.js (top frame, not on Tailscale login/admin pages).
const DAPP_PROVIDER = function () {
/*@DAPP_PROVIDER_SCRIPT@*/
};

function inMainWorld(func) {
  try {
    if (typeof contextBridge.executeInMainWorld === "function") contextBridge.executeInMainWorld({ func });
    else webFrame.executeJavaScript(`(${func.toString()})()`);
  } catch {}
}

const host = String(location.hostname || "").toLowerCase();
const tailscale = host === "tailscale.com" || host.endsWith(".tailscale.com");
if (window.top === window) {
  inMainWorld(EDGE_GRIP);
  if (!tailscale) inMainWorld(DAPP_PROVIDER);
}
